blocks.text:
I decided to leave the IFT eval until the end so that I could check all of the models
from these experiments together, so it was time to upload this one to Hugging Face,
and move on to the next model.

{
    "seed": 42,
    "tokens_desired": 10000000000,
    "upload_dataset_name": "gpjt/fw-fwedu-5050-gpt2-tokens",
    "sources": [
        {
            "name": "FineWeb",
            "hf_id": "HuggingFaceFW/fineweb",
            "hf_name": "sample-10BT",
            "hf_split": "train",
            "item_field": "text",
            "weight": 50
        },
        {
            "name": "FineWeb-Edu",
            "hf_id": "HuggingFaceFW/fineweb-edu",
            "hf_name": "sample-10BT",
            "hf_split": "train",
            "item_field": "text",
            "weight": 50
        }
    ]
}

{
    "seed": 42,
    "tokens_desired": 10000000000,
    "upload_dataset_name": "gpjt/openwebtext-gpt2-tokens",
    "sources": [
        {
            "name": "OpenWebText",
            "hf_id": "Skylion007/openwebtext",
            "hf_name": "plain_text",
            "hf_split": "train",
            "item_field": "text",
            "weight": 50
        }
    ]
}

